import React, { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import QRCode from 'qrcode';
import './styles.css';
import SafeImage from './components/common/SafeImage.jsx';
import ProductsSection from './components/product/ProductsSection.jsx';
import { CATEGORIES as categories, CATEGORY_IMAGES as categoryImages } from './constants/catalogue.js';
import { api, authenticateAccount, formatPrice, imageUrl } from './services/api.js';

const AdminPortal = lazy(() => import('./admin.jsx'));

function ProtectedCheckout({ setPage, ...props }) { const [state, setState] = useState('loading'); useEffect(() => { api('/customer/auth/me').then(() => setState('ready')).catch(() => { sessionStorage.setItem('nh_return_to_checkout', '1'); setPage('profile'); }); }, []); if (state !== 'ready') return <section className="section checkout-page"><LoadingState label="Checking your account…" /></section>; return <Checkout setPage={setPage} {...props} />; }

const CART_STORAGE_KEY = 'national-handicrafts-cart';

function useCart() {
  const [cart, setCart] = useState(() => { try { const saved = JSON.parse(localStorage.getItem(CART_STORAGE_KEY) || '[]'); return Array.isArray(saved) ? saved : []; } catch { return []; } });
  useEffect(() => { localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(cart)); }, [cart]);
  const addToCart = (product) => setCart((current) => {
    const existing = current.find((item) => item.id === product.id);
    const nextQuantity = (existing?.quantity || 0) + 1;
    if (product.stock !== null && product.stock !== undefined && nextQuantity > product.stock) return current;
    const snapshot = { id: product.id, name: product.name, category: product.category, price_inr: product.price_inr, stock: product.stock, image_path: product.image_path || null };
    return existing ? current.map((item) => item.id === product.id ? { ...item, ...snapshot, quantity: nextQuantity } : item) : [...current, { ...snapshot, quantity: 1 }];
  });
  const setQuantity = (id, quantity) => setCart((current) => current.map((item) => item.id === id ? { ...item, quantity: Math.max(1, Math.floor(quantity)) } : item));
  const removeFromCart = (id) => setCart((current) => current.filter((item) => item.id !== id));
  const clearCart = () => setCart([]);
  const reconcile = (products) => setCart((current) => { const byId = new Map(products.map((product) => [product.id, product])); return current.map((item) => { const product = byId.get(item.id); if (!product) return null; const quantity = product.stock == null ? item.quantity : Math.min(item.quantity, product.stock); return { ...item, ...product, quantity }; }).filter((item) => item && item.quantity > 0); });
  return { cart, addToCart, setQuantity, removeFromCart, clearCart, reconcile };
}

function App() {
  const params = new URLSearchParams(location.search);
  const initialSection = ['about', 'products'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'home';
  const [page, setPage] = useState(location.pathname === '/profile' ? 'profile' : params.get('admin') === '1' ? 'admin' : params.get('product') ? 'detail' : params.get('page') || initialSection);
  const [selectedProductId, setSelectedProductId] = useState(params.get('product'));
  const [checkoutItems, setCheckoutItems] = useState([]);
  const [products, setProducts] = useState([]);
  const [catalogueState, setCatalogueState] = useState('loading');
  const [catalogueError, setCatalogueError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [appReady, setAppReady] = useState(false);
  const { cart, addToCart, setQuantity, removeFromCart, clearCart, reconcile } = useCart();
  const refresh = () => { setCatalogueState('loading'); setCatalogueError(''); return api('/products').then((r) => { const nextProducts = Array.isArray(r?.data) ? r.data : []; setProducts(nextProducts); reconcile(nextProducts); setCatalogueState('ready'); setAppReady(true); return nextProducts; }).catch((error) => { setCatalogueState('error'); setCatalogueError(error.message); setProducts([]); setAppReady(true); }); };
  useEffect(() => { refresh(); const onPopState = () => { const nextParams = new URLSearchParams(location.search); const nextPage = location.pathname === '/profile' ? 'profile' : nextParams.get('admin') === '1' ? 'admin' : nextParams.get('product') ? 'detail' : nextParams.get('page') || (['about', 'products'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'home'); setSelectedProductId(nextParams.get('product')); setPage(nextPage); requestAnimationFrame(() => { if (['home', 'products'].includes(nextPage)) document.getElementById(nextPage)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }); }; addEventListener('popstate', onPopState); return () => removeEventListener('popstate', onPopState); }, []);
  useEffect(() => { if (['about', 'products'].includes(page)) requestAnimationFrame(() => document.getElementById(page)?.scrollIntoView({ block: 'start' })); }, []);
  const navigate = (nextPage) => { const landingPage = ['home', 'products'].includes(nextPage); setPage(nextPage); if (nextPage !== 'detail') setSelectedProductId(null); if (landingPage) { history.pushState({}, '', nextPage === 'home' ? location.pathname : `${location.pathname}#${nextPage}`); requestAnimationFrame(() => document.getElementById(nextPage)?.scrollIntoView({ behavior: 'smooth', block: 'start' })); } else if (nextPage === 'profile') history.pushState({}, '', '/profile'); else if (['about', 'contact', 'cart'].includes(nextPage)) history.pushState({}, '', `${location.pathname}?page=${nextPage}`); };
  const openProduct = (id) => { setSelectedProductId(id); setPage('detail'); history.pushState({}, '', `${location.pathname}?product=${encodeURIComponent(id)}`); };
  const requireCheckout = async (items) => { try { await api('/customer/auth/me'); setCheckoutItems(items); navigate('checkout'); } catch { setCheckoutItems(items); sessionStorage.setItem('nh_return_to_checkout', '1'); navigate('profile'); } };
  const buyNow = (product) => requireCheckout([{ id: product.id, name: product.name, category: product.category, price_inr: product.price_inr, stock: product.stock, image_path: product.image_path || null, quantity: 1 }]);
  const checkoutCart = () => requireCheckout(cart);
  if (!appReady) return <LoadingScreen />;
  return <><SiteNavigationV2 page={page} setPage={navigate} cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)} searchQuery={searchQuery} setSearchQuery={setSearchQuery} /><main>
    {['home', 'products'].includes(page) && <><LandingHero setPage={navigate} /><div id="products" className="scroll-section"><ProductsSection products={products} refresh={refresh} openProduct={openProduct} addToCart={addToCart} buyNow={buyNow} catalogueState={catalogueState} catalogueError={catalogueError} searchQuery={searchQuery} setSearchQuery={setSearchQuery} /></div></>}
    {page === 'about' && <div id="about" className="scroll-section"><About /></div>}
    {page === 'detail' && <ProductDetailV2 id={selectedProductId} setPage={navigate} addToCart={addToCart} buyNow={buyNow} />}
    {page === 'contact' && <Contact />}
    {page === 'profile' && <CustomerProfile setPage={navigate} />}
    {page === 'cart' && <ProtectedCheckout setPage={navigate} items={cart} setQuantity={setQuantity} clearCart={clearCart} isCart />}
    {page === 'checkout' && <ProtectedCheckout setPage={navigate} items={checkoutItems} setQuantity={setQuantity} />}
    {page === 'admin' && <Suspense fallback={<section className="section admin-page"><LoadingState label="Loading the admin portal…" /></section>}><AdminPortal refresh={refresh} /></Suspense>}
  </main><Footer setPage={navigate} /></>;
}

 function Header({ page, setPage, cartCount }) { const [open, setOpen] = useState(false); const go = (nextPage) => { setPage(nextPage); setOpen(false); }; return <header className="site-header"><button className="brand" onClick={() => go('home')}><SafeImage src="/assets/heritage-emblem.png" alt="National Handicrafts emblem" /><span><b>National</b><small>Handicrafts Bengaluru</small></span></button><button className="menu-toggle" onClick={() => setOpen(!open)} aria-expanded={open}><span>{open ? 'Close' : 'Menu'}</span><i aria-hidden="true">{open ? '×' : 'Menu'}</i></button><nav className={open ? 'open' : ''} aria-label="Primary navigation">{[['home', 'Home'], ['about', 'About'], ['products', 'Products'], ['contact', 'Contact']].map(([id, label]) => <button className={page === id ? 'active' : ''} key={id} onClick={() => go(id)}>{label}</button>)}<button className={page === 'cart' ? 'active cart-link' : 'cart-link'} onClick={() => go('cart')}>Cart{cartCount > 0 && <span>{cartCount}</span>}</button></nav></header>; }
function HeaderWithIcons({ page, setPage, cartCount }) { const [open, setOpen] = useState(false); const [searchOpen, setSearchOpen] = useState(false); const [query, setQuery] = useState(''); const go = (nextPage) => { setPage(nextPage); setOpen(false); }; const submitSearch = (event) => { event.preventDefault(); const input = document.querySelector('.products-page .toolbar input'); if (input) { const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set; setter?.call(input, query); input.dispatchEvent(new Event('input', { bubbles: true })); } go('products'); setSearchOpen(false); }; return <header className="site-header"><button className="brand" onClick={() => go('home')}><SafeImage src="/assets/heritage-emblem.png" alt="National Handicrafts emblem" /><span><b>National</b><small>Handicrafts Bengaluru</small></span></button><button className="menu-toggle" onClick={() => setOpen(!open)} aria-expanded={open}><span>{open ? 'Close' : 'Menu'}</span><i aria-hidden="true">{open ? '×' : 'Menu'}</i></button><nav className={open ? 'open' : ''} aria-label="Primary navigation">{[['home', 'Home'], ['about', 'About'], ['products', 'Products'], ['contact', 'Contact']].map(([id, label]) => <button className={page === id ? 'active' : ''} key={id} onClick={() => go(id)}>{label}</button>)}</nav><div className="header-actions"><button className="nav-icon-button" aria-label="Search products" aria-expanded={searchOpen} onClick={() => setSearchOpen((value) => !value)}><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5" /><path d="m16 16 5 5" /></svg></button><button className={page === 'cart' ? 'nav-icon-button cart-icon active' : 'nav-icon-button cart-icon'} aria-label={`Shopping bag${cartCount > 0 ? `, ${cartCount} items` : ''}`} onClick={() => go('cart')}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8.5h14l-1 12H6l-1-12Z" /><path d="M9 9V7a3 3 0 0 1 6 0v2" /></svg>{cartCount > 0 && <span>{cartCount}</span>}</button></div>{searchOpen && <form className="header-search" onSubmit={submitSearch} role="search"><label htmlFor="header-product-search">Search products</label><input id="header-product-search" autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search the catalogue" /><button className="button primary" type="submit">Search</button></form>}</header>; }
function SiteNavigation({ page, setPage, cartCount, searchQuery, setSearchQuery }) {
  const [open, setOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const go = (nextPage) => { setPage(nextPage); setOpen(false); setSearchOpen(false); };
  const submitSearch = (event) => { event.preventDefault(); setSearchQuery(event.currentTarget.elements.search.value); setPage('products'); setOpen(false); setSearchOpen(false); };
  return <header className="site-header"><button className="brand" onClick={() => go('home')}><SafeImage src="/assets/heritage-emblem.png" alt="National Handicrafts emblem" /><span><b>National</b><small>Handicrafts Bengaluru</small></span></button><button className="menu-toggle" onClick={() => setOpen(!open)} aria-expanded={open}><span>{open ? 'Close' : 'Menu'}</span><i aria-hidden="true">{open ? '×' : 'Menu'}</i></button><nav className={open ? 'open' : ''} aria-label="Primary navigation">{[['home', 'Home'], ['products', 'Products'], ['about', 'About'], ['contact', 'Contact']].map(([id, label]) => <button className={page === id ? 'active' : ''} key={id} onClick={() => go(id)}>{label}</button>)}</nav><div className="header-actions"><button className="nav-icon-button" aria-label="Search products" aria-expanded={searchOpen} onClick={() => setSearchOpen((value) => !value)}><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5" /><path d="m16 16 5 5" /></svg></button><button className={page === 'cart' ? 'nav-icon-button cart-icon active' : 'nav-icon-button cart-icon'} aria-label={`Shopping bag${cartCount > 0 ? `, ${cartCount} items` : ''}`} onClick={() => go('cart')}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8.5h14l-1 12H6l-1-12Z" /><path d="M9 9V7a3 3 0 0 1 6 0v2" /></svg>{cartCount > 0 && <span>{cartCount}</span>}</button></div>{searchOpen && <form className="header-search" onSubmit={submitSearch} role="search"><label htmlFor="header-product-search">Search products</label><input id="header-product-search" name="search" autoFocus value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} placeholder="Search the catalogue" /><button className="button primary" type="submit">Search</button><button className="header-search-close" type="button" aria-label="Close search" onClick={() => setSearchOpen(false)}>×</button></form>}</header>;
}
function SiteNavigationV2({ page, setPage, cartCount, searchQuery, setSearchQuery }) {
  const [open, setOpen] = useState(false);
  const go = (nextPage) => { setPage(nextPage); setOpen(false); };
  const submitSearch = (event) => { event.preventDefault(); setPage('products'); setOpen(false); };
  return <header className="site-header"><button className="brand" onClick={() => go('home')}><SafeImage src="/assets/heritage-emblem.png" alt="National Handicrafts emblem" /><span><b>National</b><small>Handicrafts Bengaluru</small></span></button><form className="header-search" onSubmit={submitSearch} role="search"><label htmlFor="header-product-search">Search the catalogue</label><span className="header-search-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5" /><path d="m16 16 5 5" /></svg></span><input id="header-product-search" name="search" value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} placeholder="Search handicrafts, products and categories" /><button className="header-search-submit" type="submit" aria-label="Search catalogue"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5" /><path d="m16 16 5 5" /></svg></button>{searchQuery && <button className="header-search-clear" type="button" aria-label="Clear search" onClick={() => setSearchQuery('')}>×</button>}</form><button className="menu-toggle" onClick={() => setOpen(!open)} aria-expanded={open}><span>{open ? 'Close' : 'Menu'}</span><i aria-hidden="true">{open ? '×' : 'Menu'}</i></button><nav className={open ? 'open' : ''} aria-label="Primary navigation">{[['home', 'Home'], ['products', 'Products'], ['about', 'About'], ['contact', 'Contact']].map(([id, label]) => <button className={page === id ? 'active' : ''} key={id} onClick={() => go(id)}>{label}</button>)}</nav><div className="header-actions"><button className={page === 'cart' ? 'nav-icon-button cart-icon active' : 'nav-icon-button cart-icon'} aria-label={`Shopping bag${cartCount > 0 ? `, ${cartCount} items` : ''}`} onClick={() => go('cart')}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8.5h14l-1 12H6l-1-12Z" /><path d="M9 9V7a3 3 0 0 1 6 0v2" /></svg>{cartCount > 0 && <span>{cartCount}</span>}</button><button className={page === 'profile' ? 'nav-icon-button profile-icon active' : 'nav-icon-button profile-icon'} aria-label="Your profile" onClick={() => go('profile')}><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.4" /><path d="M5.5 20c.8-3.4 3.1-5.1 6.5-5.1s5.7 1.7 6.5 5.1" /></svg></button></div></header>;
}
function LoadingState({ label = 'Loading the catalogue…' }) { return <div className="status-state" role="status"><p>{label}</p></div>; }
function LoadingScreen() { return <div className="app-loading-screen" role="status" aria-live="polite"><div className="app-loading-inner"><img src="/assets/heritage-emblem.png" alt="National Handicrafts Bengaluru" /><p className="app-loading-brand">National Handicrafts Bengaluru</p><div className="app-loading-track" aria-hidden="true"><span /></div><p className="app-loading-caption">Crafting something special…</p></div></div>; }

function GoogleSignIn({ onSuccess, onError }) { const host = useRef(null); useEffect(() => { const clientId = import.meta.env.VITE_GOOGLE_CLIENT_ID; const report = (message) => { if (import.meta.env.DEV) onError?.(message); }; if (!clientId) { report('Google sign-in needs VITE_GOOGLE_CLIENT_ID in the development environment.'); return undefined; } const render = () => { if (!host.current || !window.google?.accounts?.id) return; window.google.accounts.id.initialize({ client_id: clientId, callback: (response) => onSuccess?.(response.credential) }); window.google.accounts.id.renderButton(host.current, { theme: 'filled_blue', size: 'large', text: 'continue_with', shape: 'rectangular', width: Math.min(360, host.current.clientWidth || 360) }); }; if (window.google?.accounts?.id) render(); else { const script = document.createElement('script'); script.src = 'https://accounts.google.com/gsi/client'; script.async = true; script.onload = render; script.onerror = () => report('Google sign-in could not be loaded.'); document.head.appendChild(script); } return undefined; }, [onSuccess, onError]); return <div className="google-signin" ref={host} aria-label="Continue with Google" />; }
function LandingHero({ setPage }) { return <section id="home" className="hero section"><div className="hero-copy"><p className="section-label">National Handicrafts Bengaluru</p><h1>Craft for every day.</h1><p className="lede">Verified brass, copper, puja, dining and decorative objects, presented with the care they deserve.</p><button className="button primary" onClick={() => setPage('products')}>Explore the collection →</button></div><div className="hero-art"><SafeImage src="/assets/hanging-brass-lanterns.png" alt="Handcrafted brass hanging lanterns" loading="eager" fetchPriority="high" width={700} height={650} /></div></section>; }
function ErrorState({ onRetry, message }) { return <div className="status-state error-state" role="alert"><p>We could not load the catalogue.</p><span>{message || 'Check that the API is running, then try again.'}</span>{onRetry && <button className="button secondary" onClick={onRetry}>Try again</button>}</div>; }
function Home({ setPage, openProduct, addToCart, buyNow, products, catalogueState, catalogueError, refresh }) { return <><section className="hero section"><div className="hero-copy"><p className="section-label">National Handicrafts Bengaluru</p><h1>Craft for every day.</h1><p className="lede">Verified brass, copper, puja, dining and decorative objects, presented with the care they deserve.</p><button className="button primary" onClick={() => setPage('products')}>Explore the collection →</button></div><div className="hero-art"><SafeImage src="/assets/open-vessel-reference.png" alt="Open brass vessel reference" /></div></section><section className="section intro"><div><p className="section-label">The collection</p><h2>Familiar forms, thoughtfully chosen.</h2></div><p>Every public product record is reviewed before it reaches the collection. Browse by material and ritual, then enquire or buy when the verified details are ready.</p></section><section className="section category-grid"><div className="category-heading"><h2>Shop by material and ritual.</h2><button className="text-button" onClick={() => setPage('products')}>View all products →</button></div>{categories.map((name) => <button className="category-tile" key={name} onClick={() => setPage('products')}><SafeImage src={categoryImages[name]} alt={`${name} reference`} /><span>{name}</span><small>Explore collection →</small></button>)}</section><section className="section feature-band"><div><p className="section-label">A quiet kind of luxury</p><h2>Traditional material, modern pace.</h2><p>The catalogue stays clear about what has and has not been verified, so every choice begins with trustworthy detail.</p><button className="text-button" onClick={() => setPage('about')}>Read our story →</button></div><div className="feature-orbit"><SafeImage src="/assets/elephant-reference.png" alt="Decorative elephant reference" /></div></section><section className="section featured"><div className="section-heading"><div><p className="section-label">Selected pieces</p><h2>{products.length ? 'Published from the catalogue.' : 'Verified pieces will appear here.'}</h2></div><button className="text-button" onClick={() => setPage('products')}>Open catalogue →</button></div>{catalogueState === 'loading' ? <LoadingState /> : catalogueState === 'error' ? <ErrorState onRetry={refresh} message={catalogueError} /> : products.length ? <div className="product-grid">{products.slice(0, 3).map((product) => <ProductCard key={product.id} product={product} openProduct={openProduct} addToCart={addToCart} buyNow={buyNow} />)}</div> : <div className="verified-empty"><p>No verified product records are published yet.</p><span>An administrator can publish reviewed product records from the admin portal.</span></div>}</section></>; }
function About() { return <section className="section page-content"><div className="about-copy"><p className="eyebrow">ABOUT NATIONAL HANDICRAFTS</p><h1>Traditional craft, presented with clarity.</h1><p className="lede">A considered digital catalogue for Indian brass, copper, puja and dining objects.</p><p>This foundation keeps source references visible and leaves uncertain catalogue details unpublished until they are reviewed.</p></div><div className="about-mark"><SafeImage src="/assets/heritage-emblem.png" alt="National Handicrafts heritage emblem" /></div></section>; }
function LegacyProductCard({ product, openProduct, addToCart, buyNow }) { const canBuy = product.stock !== 0 && product.price_inr != null; return <article className="product-card" tabIndex="0" role="link" onClick={() => openProduct(product.id)} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); openProduct(product.id); } }}><div className="product-image"><SafeImage src={imageUrl(product.image_path)} alt={product.name} /></div><div className="product-meta"><p className="eyebrow">{product.category}</p><h3>{product.name}</h3><div className="product-bottom"><span>{formatPrice(product.price_inr)}</span><small>{product.stock === 0 ? 'Out of stock' : 'Available'}</small></div><div className="card-actions"><button className="button secondary card-action" disabled={!canBuy} onClick={(event) => { event.stopPropagation(); addToCart(product); }}>Add to cart</button><button className="button primary card-action" disabled={!canBuy} onClick={(event) => { event.stopPropagation(); buyNow(product); }}>{canBuy ? 'Buy now' : 'Unavailable'}</button></div></div></article>; }
function LegacyProducts({ products, refresh, openProduct, addToCart, buyNow, catalogueState, catalogueError }) { const [q, setQ] = useState(''); const [category, setCategory] = useState(''); const filtered = products.filter((p) => (!category || p.category === category) && (!q || `${p.name} ${p.category}`.toLowerCase().includes(q.toLowerCase()))); return <section className="section products-page"><div className="page-heading"><div><p className="eyebrow">THE CATALOGUE</p><h1>Find a piece with presence.</h1></div><p>Only active, verified products appear in this customer-facing collection.</p></div><div className="toolbar"><input aria-label="Search products" placeholder="Search products" value={q} onChange={(e) => setQ(e.target.value)} /><select aria-label="Filter by category" value={category} onChange={(e) => setCategory(e.target.value)}><option value="">All categories</option>{categories.map((c) => <option key={c}>{c}</option>)}</select><button className="text-button" onClick={refresh}>Refresh</button></div>{catalogueState === 'loading' ? <LoadingState /> : catalogueState === 'error' ? <ErrorState onRetry={refresh} message={catalogueError} /> : filtered.length ? <div className="product-grid">{filtered.map((product) => <ProductCard key={product.id} product={product} openProduct={openProduct} addToCart={addToCart} buyNow={buyNow} />)}</div> : <div className="verified-empty"><p>No matching verified products.</p><span>Product records added and verified in the admin portal appear here automatically.</span></div>}</section>; }
function Products({ products, refresh, openProduct, addToCart, buyNow, catalogueState, catalogueError, searchQuery, setSearchQuery }) { const [category, setCategory] = useState(''); const [filtersOpen, setFiltersOpen] = useState(false); const filtered = products.filter((p) => (!category || p.category === category) && (!searchQuery || `${p.name} ${p.category}`.toLowerCase().includes(searchQuery.toLowerCase()))); return <section className="section products-page"><div className="page-heading"><div><p className="eyebrow">THE CATALOGUE</p><h1>Find a piece with presence.</h1></div><p>Only active, verified products appear in this customer-facing collection.</p></div><div className="toolbar"><label className="product-search"><span aria-hidden="true">⌕</span><input aria-label="Search products" placeholder="Search products" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} /></label><button className="filter-toggle" type="button" aria-expanded={filtersOpen} onClick={() => setFiltersOpen((value) => !value)}>Filters <span aria-hidden="true">{filtersOpen ? '−' : '+'}</span></button><button className="text-button product-refresh" onClick={refresh}>Refresh</button></div><div className="category-chips" aria-label="Product categories"><button className={!category ? 'active' : ''} onClick={() => setCategory('')}>All</button>{categories.map((c) => <button className={category === c ? 'active' : ''} key={c} onClick={() => setCategory(c)}>{c}</button>)}</div>{filtersOpen && <div className="mobile-filter-panel"><label htmlFor="product-category-filter">Category<select id="product-category-filter" aria-label="Filter by category" value={category} onChange={(e) => setCategory(e.target.value)}><option value="">All categories</option>{categories.map((c) => <option key={c}>{c}</option>)}</select></label><button className="button secondary" type="button" onClick={() => setFiltersOpen(false)}>Done</button></div>}{catalogueState === 'loading' ? <LoadingState /> : catalogueState === 'error' ? <ErrorState onRetry={refresh} message={catalogueError} /> : filtered.length ? <div className="product-grid">{filtered.map((product) => <ProductCard key={product.id} product={product} openProduct={openProduct} addToCart={addToCart} buyNow={buyNow} />)}</div> : <div className="verified-empty"><p>No matching verified products.</p><span>Product records added and verified in the admin portal appear here automatically.</span></div>}</section>; }
function ProductDetail({ id, setPage, addToCart, buyNow }) { const [state, setState] = useState({ status: 'loading', product: null, error: '' }); const load = () => { if (!id) { setState({ status: 'error', product: null, error: 'Product not found.' }); return; } setState({ status: 'loading', product: null, error: '' }); api(`/products/${encodeURIComponent(id)}`).then((response) => setState({ status: 'ready', product: response.data, error: '' })).catch((error) => setState({ status: 'error', product: null, error: error.message })); }; useEffect(load, [id]); if (state.status === 'loading') return <section className="section"><LoadingState label="Loading product details…" /></section>; if (state.status === 'error') return <section className="section page-content"><p className="eyebrow">PRODUCT DETAILS</p><h1>That piece is not available.</h1><p className="lede">{state.error || 'This product may have been unpublished or could not be found.'}</p><button className="button secondary" onClick={() => setPage('products')}>Back to catalogue</button><button className="text-button detail-retry" onClick={load}>Try again</button></section>; const product = state.product; const canBuy = product.stock !== 0 && product.price_inr != null; return <section className="section detail-page"><button className="back-link" onClick={() => setPage('products')}>← Back to catalogue</button><div className="detail-grid"><div className="detail-image"><SafeImage src={imageUrl(product.image_path)} alt={product.name} /></div><div className="detail-copy"><p className="eyebrow">{product.category}</p><h1>{product.name}</h1><p className="price-large">{formatPrice(product.price_inr)}</p>{product.description && <p className="lede">{product.description}</p>}<div className="verification"><span>{product.stock === 0 ? 'Currently out of stock' : 'Available to order'}</span><small>Published from a verified catalogue record.</small></div><div className="detail-actions"><button className="button secondary" disabled={!canBuy} onClick={() => addToCart(product)}>{canBuy ? 'Add to cart' : 'Unavailable'}</button><button className="button primary" disabled={!canBuy} onClick={() => buyNow(product)}>{canBuy ? 'Buy now' : 'Price unavailable'}</button></div><p className="fine-print">Payment remains pending until independently verified by the administrator. No payment credentials are stored.</p></div></div></section>; }
function Cart({ setPage, cart, setQuantity, removeFromCart, clearCart }) { const [customer, setCustomer] = useState({ name: '', email: '', phone: '', message: '' }); const [status, setStatus] = useState({ type: 'idle', message: '' }); const subtotal = cart.some((item) => item.price_inr == null) ? null : cart.reduce((sum, item) => sum + Number(item.price_inr) * item.quantity, 0); const updateQuantity = (item, amount) => { const next = item.quantity + amount; if (next < 1 || (item.stock != null && next > item.stock)) return; setQuantity(item.id, next); }; const submit = async (event) => { event.preventDefault(); setStatus({ type: 'submitting', message: '' }); try { const response = await api('/orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ customer, items: cart.map((item) => ({ id: item.id, quantity: item.quantity })) }) }); clearCart(); setStatus({ type: 'success', message: `Your enquiry ${response.data.id} has been received. We will confirm availability and pricing separately.` }); } catch (error) { setStatus({ type: 'error', message: error.message }); } }; return <section className="section cart-page"><p className="eyebrow">CART AND ENQUIRY</p><h1>{cart.length ? 'Review your pieces.' : 'Your cart is quiet for now.'}</h1>{status.type === 'success' ? <div className="success-state" role="status"><p>{status.message}</p><button className="button secondary" onClick={() => setPage('products')}>Continue browsing</button></div> : cart.length ? <div className="cart-layout"><div><div className="cart-items">{cart.map((item) => <div className="cart-item" key={item.id}><SafeImage src={imageUrl(item.image_path) || categoryImages[item.category]} alt={item.name} /><div><p className="eyebrow">{item.category}</p><h3>{item.name}</h3><span>{formatPrice(item.price_inr)}</span><div className="quantity"><button aria-label={`Decrease quantity of ${item.name}`} onClick={() => updateQuantity(item, -1)}>−</button><span>{item.quantity}</span><button aria-label={`Increase quantity of ${item.name}`} disabled={item.stock != null && item.quantity >= item.stock} onClick={() => updateQuantity(item, 1)}>+</button></div></div><button className="remove" onClick={() => removeFromCart(item.id)}>Remove</button></div>)}</div><button className="text-button" onClick={clearCart}>Clear cart</button></div><div className="summary"><h2>Enquire about these pieces</h2><div><span>Items</span><span>{cart.reduce((sum, item) => sum + item.quantity, 0)}</span></div><div><span>Subtotal</span><b>{formatPrice(subtotal)}</b></div><p className="fine-print">The server recalculates the order from current verified catalogue prices. This displayed subtotal is only an estimate.</p><form className="checkout-form" onSubmit={submit}><label>Name<input required value={customer.name} onChange={(e) => setCustomer({ ...customer, name: e.target.value })} /></label><label>Email<input required type="email" value={customer.email} onChange={(e) => setCustomer({ ...customer, email: e.target.value })} /></label><label>Phone <span>(optional)</span><input value={customer.phone} onChange={(e) => setCustomer({ ...customer, phone: e.target.value })} /></label><label>Message <span>(optional)</span><textarea rows="3" value={customer.message} onChange={(e) => setCustomer({ ...customer, message: e.target.value })} /></label>{status.type === 'error' && <p className="form-error" role="alert">{status.message}</p>}<button className="button primary" disabled={status.type === 'submitting'}>{status.type === 'submitting' ? 'Sending enquiry…' : 'Send enquiry'}</button></form></div></div> : <div className="empty-state"><p>Your saved cart has no verified pieces yet.</p><button className="button secondary" onClick={() => setPage('products')}>Browse catalogue</button></div>}</section>; }
function Checkout({ setPage, items, setQuantity, clearCart, isCart = false }) { const [customer, setCustomer] = useState({ name: '', phone: '', email: '', address: '', city: '', state: '', pin: '', instructions: '' }); const [status, setStatus] = useState({ type: 'idle', message: '' }); const [order, setOrder] = useState(null); const subtotal = items.some((item) => item.price_inr == null) ? null : items.reduce((sum, item) => sum + Number(item.price_inr) * item.quantity, 0); const update = (key, value) => setCustomer((current) => ({ ...current, [key]: value })); const adjust = (item, amount) => { const next = item.quantity + amount; if (next < 1 || (item.stock != null && next > item.stock)) return; setQuantity(item.id, next); }; const submit = async (event) => { event.preventDefault(); if (!items.length) return; setStatus({ type: 'submitting', message: '' }); const idempotencyKey = crypto.randomUUID(); try { const response = await api('/orders', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Idempotency-Key': idempotencyKey }, body: JSON.stringify({ customer, paymentMethod: 'COD', items: items.map((item) => ({ id: item.id, quantity: item.quantity })) }) }); setOrder(response.data); if (isCart) clearCart?.(); setStatus({ type: 'success', message: '' }); } catch (error) { setStatus({ type: 'error', message: error.message }); } }; if (order) return <section className="section checkout-page"><p className="eyebrow">ORDER RECEIVED</p><h1>Thank you. Your order is reserved.</h1><div className="success-state"><p>Order reference: <strong>{order.id}</strong></p><p>Payment method: <strong>Cash on Delivery</strong></p><p>Payment status: <strong>Pending — payment is collected on delivery for COD orders.</strong></p></div><button className="button secondary" onClick={() => setPage('products')}>Continue browsing</button></section>; if (!items.length) return <section className="section empty-state"><p>Your checkout has no verified pieces.</p><button className="button secondary" onClick={() => setPage('products')}>Browse catalogue</button></section>; return <section className="section checkout-page"><p className="eyebrow">SECURE CHECKOUT</p><h1>{isCart ? 'Review your order.' : 'Complete your order.'}</h1><div className="checkout-layout"><div className="checkout-summary"><h2>Order summary</h2>{items.map((item) => <div className="checkout-item" key={item.id}><SafeImage src={imageUrl(item.image_path) || categoryImages[item.category]} alt={item.name} /><div><strong>{item.name}</strong><span>{formatPrice(item.price_inr)} each</span><div className="quantity"><button type="button" onClick={() => adjust(item, -1)}>−</button><span>{item.quantity}</span><button type="button" onClick={() => adjust(item, 1)} disabled={item.stock != null && item.quantity >= item.stock}>+</button></div></div></div>)}<div className="summary-total"><span>Total</span><strong>{formatPrice(subtotal)}</strong></div><p className="fine-print">The server recalculates prices and stock when this order is submitted.</p></div><form className="checkout-form checkout-details" onSubmit={submit}><h2>Delivery details</h2><label>Full name<input required value={customer.name} onChange={(e) => update('name', e.target.value)} /></label><label>Mobile number<input required inputMode="tel" value={customer.phone} onChange={(e) => update('phone', e.target.value)} /></label><label>Email address<input required type="email" value={customer.email} onChange={(e) => update('email', e.target.value)} /></label><label>Delivery address<textarea required rows="3" value={customer.address} onChange={(e) => update('address', e.target.value)} /></label><div className="checkout-two-column"><label>City<input required value={customer.city} onChange={(e) => update('city', e.target.value)} /></label><label>State<input required value={customer.state} onChange={(e) => update('state', e.target.value)} /></label></div><label>PIN code<input required inputMode="numeric" pattern="[0-9]{6}" maxLength="6" value={customer.pin} onChange={(e) => update('pin', e.target.value)} /></label><label>Delivery instructions <span>(optional)</span><textarea rows="2" value={customer.instructions} onChange={(e) => update('instructions', e.target.value)} /></label><fieldset className="payment-choice"><legend>Payment method</legend><label className="cod-choice"><input type="radio" name="paymentMethod" value="COD" checked readOnly /> <span><strong>Cash on Delivery</strong><small>Pay when your order arrives.</small></span></label></fieldset>{status.type === 'error' && <p className="form-error" role="alert">{status.message}</p>}<button className="button primary" disabled={status.type === 'submitting'}>{status.type === 'submitting' ? 'Creating order…' : 'Place COD order'}</button></form></div></section>; }
function PaymentPanel({ order, payment }) { const [qr, setQr] = useState(''); const configured = payment?.enabled && order?.payment_status !== 'not_configured' && order?.payment_method !== 'COD'; const intent = configured ? `upi://pay?${new URLSearchParams({ pa: payment.upiId, pn: payment.payeeName, am: String(order.total_inr), cu: 'INR', tn: order.id }).toString()}` : ''; useEffect(() => { if (intent) QRCode.toDataURL(intent, { margin: 1, width: 220 }).then(setQr).catch(() => setQr('')); }, [intent]); if (order?.payment_method === 'COD') return <p className="payment-not-configured">Your order is confirmed for Cash on Delivery. Payment remains pending until collected when the order arrives.</p>; if (!configured) return <p className="payment-not-configured">Online payment is not configured yet. Your order is recorded, and the administrator can contact you with the next steps.</p>; return <div className="payment-panel"><h2>Pay by UPI</h2><p>Pay <strong>{formatPrice(order.total_inr)}</strong> to <strong>{payment.payeeName}</strong>.</p><p className="payment-reference">Reference: <strong>{order.id}</strong></p>{qr && <img className="payment-qr" src={qr} alt="UPI payment QR code" />}<div className="payment-actions"><a className="button primary" href={intent}>Open UPI app</a><button className="button secondary" onClick={() => navigator.clipboard?.writeText(payment.upiId)}>Copy UPI ID</button></div><p className="fine-print">Payment remains pending until independently verified by National Handicrafts. Opening the app, scanning this QR code, or sharing a screenshot does not mark the order paid.</p></div>; }
function Admin({ refresh }) { return null; }
function Contact() { return <section className="section page-content"><p className="eyebrow">CONTACT</p><h1>Catalogue enquiries are open through your cart.</h1><p className="lede">Add verified pieces to your cart and send an enquiry with your contact details. Verified business contact details were not supplied in the source materials, so this site does not invent them.</p></section>; }
function Footer({ setPage }) { return <footer className="site-footer"><div><SafeImage src="/assets/heritage-emblem.png" alt="" /><p>National Handicrafts Bengaluru</p></div><div><p className="eyebrow">EXPLORE</p><button onClick={() => setPage('products')}>Products</button><button onClick={() => setPage('about')}>About</button><button onClick={() => setPage('cart')}>Cart</button><button onClick={() => setPage('admin')}>Admin</button></div><div><p className="eyebrow">CATALOGUE NOTE</p><p className="footer-note">Rates and specifications are shown only after source review.</p></div></footer>; }
function ProductDetailV2({ id, setPage, addToCart, buyNow }) { const [state, setState] = useState({ status: 'loading', product: null, error: '' }); const load = () => { if (!id) { setState({ status: 'error', product: null, error: 'Product not found.' }); return; } setState({ status: 'loading', product: null, error: '' }); api(`/products/${encodeURIComponent(id)}`).then((response) => setState({ status: 'ready', product: response.data, error: '' })).catch((error) => setState({ status: 'error', product: null, error: error.message })); }; useEffect(load, [id]); if (state.status === 'loading') return <section className="section"><LoadingState label="Loading product details…" /></section>; if (state.status === 'error') return <section className="section page-content"><p className="eyebrow">PRODUCT DETAILS</p><h1>That piece is not available.</h1><p className="lede">{state.error || 'This product may have been unpublished or could not be found.'}</p><button className="button secondary" onClick={() => setPage('products')}>Back to catalogue</button><button className="text-button detail-retry" onClick={load}>Try again</button></section>; const product = state.product; const inStock = (product.stock !== null && product.stock !== undefined && Number(product.stock) > 0) || product.availability === 'available'; const canBuy = inStock && product.price_inr != null; const detailPrice = product.price_inr == null ? 'Price on request' : `\u20B9${Number(product.price_inr).toLocaleString('en-IN')}`; return <section className="section detail-page"><button className="back-link" onClick={() => setPage('products')}>← Back to catalogue</button><div className="detail-grid"><div className="detail-image"><SafeImage src={imageUrl(product.image_path) || categoryImages[product.category]} alt={product.name} /></div><div className="detail-copy"><p className="eyebrow">{product.category}</p><h1>{product.name}</h1><p className="price-large product-detail-price" aria-label={detailPrice}>{detailPrice}</p>{product.description && <p className="lede">{product.description}</p>}<div className={`verification ${inStock ? 'is-in-stock' : 'is-unavailable'}`}><span>{inStock ? <><i aria-hidden="true" />In stock</> : product.stock === 0 || product.availability === 'out_of_stock' ? 'Out of stock' : 'Availability by enquiry'}</span><small>Published from a verified catalogue record.</small></div><div className="detail-actions"><button className="button secondary" disabled={!canBuy} onClick={() => addToCart(product)}>{canBuy ? 'Add to cart' : 'Unavailable'}</button><button className="button primary" disabled={!canBuy} onClick={() => buyNow(product)}>{canBuy ? 'Buy now' : 'Price unavailable'}</button></div><p className="fine-print">Payment remains pending until independently verified by National Handicrafts. No payment credentials are stored.</p></div></div></section>; }
function CustomerProfile({ setPage }) {
  const [authState, setAuthState] = useState('loading');
  const [mode, setMode] = useState('login');
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '', confirmPassword: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [profile, setProfile] = useState(null);
  const [draft, setDraft] = useState(null);
  const [orders, setOrders] = useState([]);
  const [addresses, setAddresses] = useState([]);
  const [csrf, setCsrf] = useState('');
  const [addressDraft, setAddressDraft] = useState({ label: '', recipientName: '', phone: '', address: '', city: '', state: '', pin: '', isDefault: false });
  const [editingAddress, setEditingAddress] = useState(null);
  const [status, setStatus] = useState({ type: '', message: '' });
  const loadAccount = async () => { const me = await api('/customer/auth/me'); const [token, orderResponse, addressResponse] = await Promise.all([api('/customer/auth/csrf'), api('/customer/orders'), api('/customer/addresses')]); setProfile(me.data); setDraft(me.data); setCsrf(token.data.token); setOrders(orderResponse.data || []); setAddresses(addressResponse.data || []); setAuthState('ready'); };
  useEffect(() => { loadAccount().catch(() => setAuthState('signed-out')); }, []);
  const submitAuth = async (event) => { event.preventDefault(); if (mode === 'register' && authForm.password !== authForm.confirmPassword) { setStatus({ type: 'error', message: 'Passwords do not match.' }); return; } setStatus({ type: 'loading', message: '' }); try { if (mode === 'login') { const account = await authenticateAccount(authForm); if (account.role === 'admin') { window.location.assign('/?admin=1'); return; } await loadAccount(); if (sessionStorage.getItem('nh_return_to_checkout')) { sessionStorage.removeItem('nh_return_to_checkout'); setPage('checkout'); } else setStatus({ type: 'success', message: 'Signed in securely.' }); return; } await api('/customer/auth/register', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: authForm.name, email: authForm.email, password: authForm.password }) }); await loadAccount(); if (sessionStorage.getItem('nh_return_to_checkout')) { sessionStorage.removeItem('nh_return_to_checkout'); setPage('checkout'); } else setStatus({ type: 'success', message: 'Your customer account is ready.' }); } catch (error) { setStatus({ type: 'error', message: error.message }); } };
  const googleSignIn = async (credential) => { setStatus({ type: 'loading', message: '' }); try { await api('/customer/auth/google', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ credential }) }); await loadAccount(); if (sessionStorage.getItem('nh_return_to_checkout')) { sessionStorage.removeItem('nh_return_to_checkout'); setPage('checkout'); } else setStatus({ type: 'success', message: 'Signed in with Google.' }); } catch (error) { setStatus({ type: 'error', message: error.message }); } };
  const saveProfile = async (event) => { event.preventDefault(); setStatus({ type: 'loading', message: '' }); try { const response = await api('/customer/profile', { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, body: JSON.stringify(draft) }); setProfile(response.data); setDraft(response.data); setStatus({ type: 'success', message: 'Profile details saved.' }); } catch (error) { setStatus({ type: 'error', message: error.message }); } };
  const saveAddress = async (event) => { event.preventDefault(); setStatus({ type: 'loading', message: '' }); try { const path = editingAddress ? `/customer/addresses/${encodeURIComponent(editingAddress)}` : '/customer/addresses'; const response = await api(path, { method: editingAddress ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, body: JSON.stringify(addressDraft) }); setAddresses((current) => editingAddress ? current.map((item) => item.id === editingAddress ? response.data : item) : [response.data, ...current]); setEditingAddress(null); setAddressDraft({ label: '', recipientName: '', phone: '', address: '', city: '', state: '', pin: '', isDefault: false }); setStatus({ type: 'success', message: 'Address saved.' }); } catch (error) { setStatus({ type: 'error', message: error.message }); } };
  const deleteAddress = async (id) => { if (!window.confirm('Remove this saved address?')) return; try { await api(`/customer/addresses/${encodeURIComponent(id)}`, { method: 'DELETE', headers: { 'X-CSRF-Token': csrf } }); setAddresses((current) => current.filter((item) => item.id !== id)); setStatus({ type: 'success', message: 'Address removed.' }); } catch (error) { setStatus({ type: 'error', message: error.message }); } };
  const logout = async () => { try { await api('/customer/auth/logout', { method: 'POST', headers: { 'X-CSRF-Token': csrf } }); } finally { setProfile(null); setAuthState('signed-out'); setPage('profile'); } };
  if (authState === 'loading') return <section className="section profile-page"><LoadingState label="Loading your profile…" /></section>;
  if (authState === 'signed-out') return <section className="section profile-auth"><div className="profile-auth-card"><img className="profile-auth-logo" src="/assets/heritage-emblem.png" alt="National Handicrafts Bengaluru" /><p className="eyebrow">YOUR ACCOUNT</p><h1>{mode === 'login' ? 'Welcome back.' : 'Create your account.'}</h1><p className="lede">Sign in or create an account to continue.</p><GoogleSignIn onSuccess={googleSignIn} onError={(message) => setStatus({ type: 'error', message })} /><div className="auth-divider"><span>or use email</span></div><form className="profile-auth-form" onSubmit={submitAuth}>{mode === 'register' && <label>Full name<input required autoComplete="name" value={authForm.name} onChange={(e) => setAuthForm({ ...authForm, name: e.target.value })} /></label>}<label>Email address<input required type="email" autoComplete="email" value={authForm.email} onChange={(e) => setAuthForm({ ...authForm, email: e.target.value })} /></label><label>Password<span className="password-field"><input required minLength="8" type={showPassword ? 'text' : 'password'} autoComplete={mode === 'login' ? 'current-password' : 'new-password'} value={authForm.password} onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })} /><button type="button" onClick={() => setShowPassword((value) => !value)} aria-label={showPassword ? 'Hide password' : 'Show password'}>{showPassword ? 'Hide' : 'Show'}</button></span></label>{mode === 'register' && <label>Confirm password<input required minLength="8" type={showPassword ? 'text' : 'password'} autoComplete="new-password" value={authForm.confirmPassword} onChange={(e) => setAuthForm({ ...authForm, confirmPassword: e.target.value })} /></label>}{status.message && <p className={status.type === 'error' ? 'form-error' : 'form-success'} role={status.type === 'error' ? 'alert' : 'status'}>{status.message}</p>}<button className="button primary" disabled={status.type === 'loading'}>{status.type === 'loading' ? 'Please wait…' : mode === 'login' ? 'Sign in' : 'Create account'}</button></form>{mode === 'login' && <button className="text-button auth-recovery" type="button" disabled>Forgot password?</button>}<button className="text-button auth-switch" onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setStatus({}); setShowPassword(false); }}>{mode === 'login' ? 'New here? Create an account' : 'Already have an account? Sign in'}</button>{import.meta.env.DEV && !import.meta.env.VITE_GOOGLE_CLIENT_ID && <p className="auth-note">Google sign-in needs VITE_GOOGLE_CLIENT_ID in the development environment.</p>}</div></section>;
  const initials = (profile?.name || profile?.email || '?').split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase();
  return <section className="section profile-page"><div className="profile-heading"><div><p className="eyebrow">YOUR ACCOUNT</p><h1>Your profile.</h1><p className="lede">A private place for your details, saved addresses, and orders.</p></div><button className="button secondary" onClick={logout}>Log out</button></div>{status.message && <p className={status.type === 'error' ? 'form-error' : 'form-success'} role={status.type === 'error' ? 'alert' : 'status'}>{status.message}</p>}<div className="profile-overview"><div className="profile-avatar" aria-hidden="true">{initials}</div><div><h2>{profile.name || 'Add your name'}</h2><p>{profile.email}</p><small>{profile.phone || 'Phone number not added'}</small></div></div><div className="profile-grid"><form className="profile-panel profile-form" onSubmit={saveProfile}><div className="profile-panel-heading"><div><p className="eyebrow">PERSONAL DETAILS</p><h2>Edit your details.</h2></div><button className="text-button" type="button" onClick={() => setDraft(profile)}>Cancel</button></div><label>Full name<input required value={draft.name || ''} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></label><label>Email address<input value={draft.email || ''} disabled /></label><label>Phone number<input value={draft.phone || ''} onChange={(e) => setDraft({ ...draft, phone: e.target.value })} /></label><label>Delivery address<textarea rows="3" value={draft.address || ''} onChange={(e) => setDraft({ ...draft, address: e.target.value })} /></label><div className="profile-two-column"><label>City<input value={draft.city || ''} onChange={(e) => setDraft({ ...draft, city: e.target.value })} /></label><label>State<input value={draft.state || ''} onChange={(e) => setDraft({ ...draft, state: e.target.value })} /></label></div><label>PIN code<input inputMode="numeric" maxLength="6" value={draft.pin || ''} onChange={(e) => setDraft({ ...draft, pin: e.target.value })} /></label><button className="button primary" disabled={status.type === 'loading'}>Save changes</button></form><div className="profile-panel"><div className="profile-panel-heading"><div><p className="eyebrow">SAVED ADDRESSES</p><h2>Delivery addresses.</h2></div><span>{addresses.length} saved</span></div>{addresses.length ? <div className="address-list">{addresses.map((address) => <div className="address-card" key={address.id}><div><strong>{address.label}</strong>{address.is_default && <span className="profile-badge">Default</span>}<p>{address.recipient_name}<br />{address.address}, {address.city}<br />{address.state} — {address.pin}<br />{address.phone}</p></div><div className="address-actions"><button className="text-button" onClick={() => { setEditingAddress(address.id); setAddressDraft({ label: address.label, recipientName: address.recipient_name, phone: address.phone, address: address.address, city: address.city, state: address.state, pin: address.pin, isDefault: address.is_default }); }}>Edit</button><button className="text-button" onClick={() => deleteAddress(address.id)}>Delete</button></div></div>)}</div> : <div className="profile-empty">No saved addresses yet.</div>}<form className="address-form" onSubmit={saveAddress}><h3>{editingAddress ? 'Edit address' : 'Add an address'}</h3><div className="profile-two-column"><label>Label<input required placeholder="Home or studio" value={addressDraft.label} onChange={(e) => setAddressDraft({ ...addressDraft, label: e.target.value })} /></label><label>Recipient name<input required value={addressDraft.recipientName} onChange={(e) => setAddressDraft({ ...addressDraft, recipientName: e.target.value })} /></label></div><label>Phone<input required value={addressDraft.phone} onChange={(e) => setAddressDraft({ ...addressDraft, phone: e.target.value })} /></label><label>Address<textarea required rows="2" value={addressDraft.address} onChange={(e) => setAddressDraft({ ...addressDraft, address: e.target.value })} /></label><div className="profile-two-column"><label>City<input required value={addressDraft.city} onChange={(e) => setAddressDraft({ ...addressDraft, city: e.target.value })} /></label><label>State<input required value={addressDraft.state} onChange={(e) => setAddressDraft({ ...addressDraft, state: e.target.value })} /></label></div><div className="profile-two-column"><label>PIN code<input required inputMode="numeric" maxLength="6" value={addressDraft.pin} onChange={(e) => setAddressDraft({ ...addressDraft, pin: e.target.value })} /></label><label className="profile-checkbox"><input type="checkbox" checked={addressDraft.isDefault} onChange={(e) => setAddressDraft({ ...addressDraft, isDefault: e.target.checked })} /> Use as default</label></div><button className="button secondary">{editingAddress ? 'Update address' : 'Save address'}</button></form></div></div><div className="profile-panel profile-orders"><div className="profile-panel-heading"><div><p className="eyebrow">ORDER HISTORY</p><h2>My orders.</h2></div><span>{orders.length} total</span></div>{orders.length ? <div className="profile-orders-list">{orders.map((order) => <article className="profile-order" key={order.id}><div><strong>{order.id}</strong><small>{new Date(order.created_at).toLocaleDateString()}</small></div><div>{(order.items || []).map((item) => <span key={`${order.id}-${item.productId}`}>{item.name} × {item.quantity}</span>)}</div><strong>{formatPrice(order.total_inr)}</strong><div><span className="profile-badge">{order.status}</span><span className="profile-badge payment">{order.payment_status}</span></div></article>)}</div> : <div className="profile-empty">You have not placed any orders yet. <button className="text-button" onClick={() => setPage('products')}>Browse the collection</button></div>}</div></section>;
}
const ProductCard = LegacyProductCard;
createRoot(document.getElementById('root')).render(<App />);
